MATCH (a:PlantItem {tag: 'H-2001'}), (b:PlantItem {tag: 'E-2001'}), (r:PlantItem {tag: 'R-2001'})
WHERE EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE y <> r)+ (b)
}
RETURN b.tag AS tag

MATCH (e:Equipment)-[:measured_by]->()-[:send_signal_to*0..]->(head:ProcessInstrumentationFunction {loop_tag: 'LSHH-39006'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'F-201'})-[:is_drawn_on]->(sheet:Sheet)
RETURN item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (e:Equipment)-[:measured_by]->(sensor:PlantItem)-[:send_signal_to*0..]->(f:ProcessInstrumentationFunction {loop_tag: 'PI-38025'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'EJ-2501'}), (b:PlantItem {tag: 'EJ-2503'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE y.tag <> 'E-2503')+ (b)
       } AS reachable

MATCH (loop:ProcessControlFunction {loop_tag: 'PIC-47002'}), (equipment:Equipment)-[:measured_by]->(sensor:PlantItem)-[:send_signal_to*0..]->(loop)
RETURN DISTINCT equipment.tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(i:PlantItem {loop_tag: 'TI-16050'})
