MATCH (a:PlantItem {tag: 'EA-1301'}), (b:PlantItem {tag: 'V-1301'}), (v:PlantItem:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (e:PlantItem {tag: 'P-2001'})-[:measured_by]->(i:PlantItem)
