MATCH (a:PlantItem {tag: 'P-4903'}), (b:PlantItem {tag: 'TK-5003'}), (excluded:PlantItem {tag: 'TK-5002'})
WHERE EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE y <> excluded)* (b)
}
RETURN a.tag AS source, b.tag AS destination

MATCH (a:PlantItem {tag: 'EA-4901'}), (b:PlantItem {tag: 'TK-5001'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS { (a)-[:line_to*1..]->(b) } AS reachable;

MATCH (s:PlantItem {tag: 'TK-1001'}), (e:PlantItem {tag: 'F-1101'})
MATCH (s)-[:line_to*1..]->(v:Valve)
