RETURN EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE y.tag <> 'FV-39010')+ (b)
} AS reachable

MATCH (a:PlantItem {tag: 'TK-103'}), (b:PlantItem {tag: 'P-502'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
