MATCH (a:PlantItem {tag: 'P-2901'}), (b:PlantItem {tag: 'V-3501'})
RETURN a.tag AS source_tag, b.tag AS destination_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem)
                    WHERE x.tag <> 'D-3001' AND y.tag <> 'D-3001')+ (b)
       } AS can_flow_without_D-3001

MATCH (a:PlantItem {tag: 'P-2901'}), (b:PlantItem {tag: 'V-3501'})
