MATCH (a:PlantItem {tag: 'F-2702'}), (b:PlantItem {tag: 'V-3501'})
WHERE EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE y.tag <> 'XV-32003')+ (b)
}
RETURN a.tag AS from_tag, b.tag AS to_tag
ORDER BY from_tag, to_tag

MATCH (a:PlantItem {tag: 'TK-101'}), (b:PlantItem {tag: 'EH-1201'})
MATCH (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN count(DISTINCT v) AS valve_count, collect(DISTINCT v.tag) AS tags

MATCH (a:PlantItem {tag: 'P-2502'}), (b:PlantItem {tag: 'P-5102'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem)
                    WHERE x.tag <> 'XV-39002' AND y.tag <> 'XV-39002')+ (b)
       } AS reachable_without_XV-39002

MATCH (a:PlantItem {tag: 'P-2502'}), (b:PlantItem {tag: 'P-5102'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem)
                    WHERE x.tag <> 'XV-39002' AND y.tag <> 'XV-39002')+ (b)
       } AS reachable_without_XV_39002

MATCH (a:PlantItem {tag: 'K-2101'}), (b:PlantItem {tag: 'V-4301'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'D-1601'}), (b:PlantItem {tag: 'EA-1601'}), (t:PlantItem {tag: 'T-1601'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE x <> t AND y <> t)+ (b)
       } AS reachable_without_t

MATCH (a:PlantItem {tag: 'E-4301'}), (b:PlantItem {tag: 'P-1603'})
MATCH p = shortestPath((a)-[:line_to*]->(b))
RETURN [n IN nodes(p) WHERE n:Equipment OR n:Valve | n.tag] AS tags vel}

MATCH (i:PlantItem {loop_tag: 'TIC-24029'})-[:is_located_in]->(s:PlantSection)
RETURN DISTINCT s.unit_id AS unit_id
ORDER BY unit_id;

MATCH (:PlantItem:Valve {tag: 'XV-24026'})-[:line_to]->(fed:PlantItem)
RETURN fed.tag AS tag
ORDER BY tag;

MATCH (:PlantItem:Valve {tag: 'XV-7002'})-[:line_to]->(item:PlantItem)
RETURN DISTINCT item.tag AS tag
