MATCH (loop:ProcessInstrumentationFunction {loop_tag: 'LSHH-39002'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
