MATCH (p:PlantItem {tag: 'P-3201'}), (v:Valve), (e:Equipment)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (p:PlantItem {tag: 'P-2001'}),
      (v:PlantItem:Valve),
      (e:PlantItem:Equipment)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'P-3602'})-[:line_to*1..]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(:PlantItem {tag: 'F-2701'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (target:Equipment:PlantItem {tag: 'R-2001'})
MATCH (u:Equipment:PlantItem)-[:line_to*1..]->(target)
MATCH (v:Valve:PlantItem)-[:line_to*0..]->(u)
WHERE EXISTS { (v)-[:line_to*1..]->(target) }
  AND NOT EXISTS {
    MATCH (v)-[:line_to*1..]->(u2:Equipment:PlantItem)
    WHERE u2 <> u AND EXISTS { (u2)-[:line_to*1..]->(target) }
  }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (p:PlantItem {tag: 'P-2001'}), (v:Valve)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (k:PlantItem {tag: 'K-1401'}), (v:Valve)
WHERE toLower(v.category) CONTAINS 'normally open'
  AND EXISTS { (k)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*0..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (:PlantItem {tag: 'P-4203'})-[:line_to*1..]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (source:PlantItem {tag: 'F-3401'}), (v:Valve)
WHERE toLower(coalesce(v.category, '')) CONTAINS 'normally open'
  AND EXISTS { (source)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (p:PlantItem {tag: 'P-3602'}), (v:Valve)
WHERE v.category = 'normally open'
  AND EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (p:PlantItem {tag: 'P-3202'}), (v:Valve)
WHERE toLower(coalesce(v.category, '')) CONTAINS 'normally open'
  AND EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (p:PlantItem {tag: 'P-901'}), (v:Valve)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
  AND toLower(coalesce(v.category, '')) CONTAINS 'normally open'
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(:PlantItem {tag: 'F-2701'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(a:PlantItem {tag: 'EA-4001'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;
